34	// ─── Studio-scope pre-flight (W9) ─────────────────────────────────────────────
35	
36	/**
37	 * Verifies that `projectId` belongs to `studioId` before any write.
38	 * Returns `{ ok: true }` when the project is found, `{ ok: false, error }` otherwise.
39	 * Mirrors the inline check in `updateProjectStatusAction` (line ~461).
40	 */
41	async function verifyProjectInStudio(
42	  supabase: Awaited<ReturnType<typeof createClient>>,
43	  studioId: string,
44	  projectId: string,
45	): Promise<{ ok: true } | { ok: false; error: string }> {
46	  const { data, error } = await supabase
47	    .from('projects')
48	    .select('id')
49	    .eq('id', projectId)
50	    .eq('studio_id', studioId)
51	    .single()
52	
53	  if (error || !data) {
54	    return { ok: false, error: 'Project not found' }
55	  }
56	  return { ok: true }
57	}
58	
59	type MutationRole = 'owner' | 'admin' | 'artist'
60	type ReadRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'
61	
62	function canWrite(role: ReadRole): role is MutationRole {
63	  return role === 'owner' || role === 'admin' || role === 'artist'
64	}
65	
66	function canAdmin(role: ReadRole): boolean {
67	  return role === 'owner' || role === 'admin'
68	}
69	
70	// ─── Reference source detection ────────────────────────────────────────────────
71	
72	type ReferenceSource = 'pinterest' | 'instagram' | 'behance' | 'upload' | 'url'
73	
74	function detectUrlSource(url: string): ReferenceSource {
75	  try {
76	    const { hostname } = new URL(url)
77	    if (hostname.includes('pinterest.')) return 'pinterest'
78	    if (hostname.includes('instagram.')) return 'instagram'
79	    if (hostname.includes('behance.')) return 'behance'
80	  } catch {
81	    // malformed URL — fall through
82	  }
83	  return 'url'
84	}
