import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { randomUUID } from 'crypto'
import { createClient, createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// ─── Constants ────────────────────────────────────────────────────────────────

const ALLOWED_MIME_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/heic',
  'image/heif',
])

const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024 // 10 MB

const MIME_TO_EXT: Record<string, string> = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/heic': 'heic',
  'image/heif': 'heic',
}

// ─── Validation ───────────────────────────────────────────────────────────────

const uploadBodySchema = z.object({
  slot_type: z.enum(['before', 'after', 'healed', 'progress'], {
    required_error: 'slot_type is required',
  }),
  session_number: z.string().optional().transform((v) => (v ? parseInt(v, 10) : undefined)),
  booking_id: z.string().uuid().optional().nullable(),
})

type UploadBody = z.infer<typeof uploadBodySchema>

// ─── Route handler ────────────────────────────────────────────────────────────

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'Rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  // Role check: guest_artists cannot upload project photos
  if (auth.role === 'guest_artist') {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  const { id: projectId } = await params

  if (!projectId || !/^[0-9a-f-]{36}$/.test(projectId)) {
    return NextResponse.json({ error: 'Invalid project ID' }, { status: 400 })
  }

  // ── Parse multipart body ──────────────────────────────────────────────────

  let formData: FormData
  try {
    formData = await req.formData()
  } catch {
    return NextResponse.json({ error: 'Invalid multipart body' }, { status: 400 })
  }

  // ── Validate fields ───────────────────────────────────────────────────────

  const rawBody: UploadBody = {
    slot_type: formData.get('slot_type') as UploadBody['slot_type'],
    session_number: (formData.get('session_number') as string | null) ?? undefined,
    booking_id: (formData.get('booking_id') as string | null) ?? undefined,
  }

  const parsed = uploadBodySchema.safeParse(rawBody)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.issues[0]?.message ?? 'Validation failed' },
      { status: 400 }
    )
  }

  const { slot_type, booking_id } = parsed.data

  // ── Validate file ─────────────────────────────────────────────────────────

  const fileValue = formData.get('file')
  if (!fileValue || !(fileValue instanceof File)) {
    return NextResponse.json({ error: 'file is required' }, { status: 400 })
  }
  const file = fileValue

  if (!ALLOWED_MIME_TYPES.has(file.type)) {
    return NextResponse.json(
      { error: `Unsupported file type: ${file.type}. Allowed: JPEG, PNG, WebP, HEIC.` },
      { status: 415 }
    )
  }

  if (file.size > MAX_FILE_SIZE_BYTES) {
    return NextResponse.json(
      { error: `File exceeds 10 MB limit (${(file.size / 1024 / 1024).toFixed(1)} MB received)` },
      { status: 413 }
    )
  }

  // ── Verify project belongs to this studio ─────────────────────────────────

  const supabase = await createClient()

  const { data: project } = await supabase
    .from('projects')
    .select('id, name, studio_id')
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!project) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  // ── Build storage path ────────────────────────────────────────────────────

  const ext = MIME_TO_EXT[file.type] ?? 'jpg'
  const fileId = randomUUID()
  const storagePath = `${auth.studioId}/${projectId}/${slot_type}/${fileId}.${ext}`

  // ── Upload to Supabase Storage (service-role bypasses storage RLS) ────────

  const srClient = createServiceRoleClient()
  const arrayBuffer = await file.arrayBuffer()
  const fileBuffer = Buffer.from(arrayBuffer)

  const { error: uploadError } = await srClient.storage
    .from('project-photos')
    .upload(storagePath, fileBuffer, {
      contentType: file.type,
      upsert: false,
    })

  if (uploadError) {
    logger.error({ uploadError, projectId, storagePath }, 'photo upload: storage write failed')
    return NextResponse.json({ error: 'Failed to upload file' }, { status: 500 })
  }

  // ── Resolve public URL ────────────────────────────────────────────────────

  const { data: publicData } = srClient.storage
    .from('project-photos')
    .getPublicUrl(storagePath)
  const publicUrl = publicData?.publicUrl ?? ''

  // ── Compute display_order ─────────────────────────────────────────────────

  const { data: lastPhoto } = await supabase
    .from('project_progress_photos')
    .select('display_order')
    .eq('project_id', projectId)
    .order('display_order', { ascending: false })
    .limit(1)
    .maybeSingle()

  const displayOrder = ((lastPhoto?.display_order) ?? -1) + 1

  // ── Insert project_progress_photos row ───────────────────────────────────

  const { data: photoRow, error: insertError } = await supabase
    .from('project_progress_photos')
    .insert({
      project_id: projectId,
      booking_id: booking_id ?? null,
      storage_path: storagePath,
      kind: slot_type,
      display_order: displayOrder,
      created_by: auth.user.id,
    })
    .select('id, storage_path, kind, booking_id, display_order, created_at')
    .single()

  if (insertError || !photoRow) {
    logger.error({ insertError, projectId, storagePath }, 'photo upload: DB insert failed')
    // Best-effort cleanup
    await srClient.storage.from('project-photos').remove([storagePath]).catch(() => undefined)
    return NextResponse.json({ error: 'Failed to save photo record' }, { status: 500 })
  }

  // ── Log activity (best-effort) ────────────────────────────────────────────

  try {
    await supabase
      .from('project_activity_log' as 'projects')
      .insert({
        project_id: projectId,
        actor_id: auth.user.id,
        event_type: 'photo_uploaded',
        details: {
          slot_type,
          kind: slot_type,
          storage_path: storagePath,
          booking_id: booking_id ?? null,
        },
      } as never)
  } catch {
    // Best-effort — do not fail the upload
  }

  const row = photoRow as {
    id: string
    storage_path: string
    kind: string
    booking_id: string | null
    display_order: number
    created_at: string
  }

  return NextResponse.json({
    photo: {
      id: row.id,
      storage_path: row.storage_path,
      public_url: publicUrl,
    },
  })
}

import { type NextRequest, NextResponse } from 'next/server'
import JSZip from 'jszip'
import { createClient, createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// ─── Slug helper ──────────────────────────────────────────────────────────────

function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 60)
}

// ─── Route handler ────────────────────────────────────────────────────────────

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const ip = getClientIp(req)
  const { success } = await expensiveRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'Rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { id: projectId } = await params

  if (!projectId || !/^[0-9a-f-]{36}$/.test(projectId)) {
    return NextResponse.json({ error: 'Invalid project ID' }, { status: 400 })
  }

  // ── Verify project belongs to this studio ─────────────────────────────────

  const supabase = await createClient()

  const { data: project } = await supabase
    .from('projects')
    .select('id, name, studio_id')
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)
    .maybeSingle()

  if (!project) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  // ── Fetch all photos for the project ─────────────────────────────────────

  const { data: photos, error: photosError } = await supabase
    .from('project_progress_photos')
    .select('id, storage_path, kind, booking_id, caption, display_order')
    .eq('project_id', projectId)
    .order('display_order', { ascending: true })

  if (photosError) {
    logger.error({ photosError, projectId }, 'photo download: fetch failed')
    return NextResponse.json({ error: 'Failed to fetch photos' }, { status: 500 })
  }

  if (!photos || photos.length === 0) {
    return NextResponse.json({ error: 'No photos to download' }, { status: 404 })
  }

  // ── Build ZIP using signed URLs from service-role client ─────────────────

  const srClient = createServiceRoleClient()
  const zip = new JSZip()

  const downloadResults = await Promise.allSettled(
    photos.map(async (photo, idx) => {
      try {
        // Get a short-lived signed URL (60 seconds — enough for the download handler)
        const { data: signedData, error: signedError } = await srClient.storage
          .from('project-photos')
          .createSignedUrl(photo.storage_path, 60)

        if (signedError || !signedData?.signedUrl) {
          throw new Error(`Failed to get signed URL for photo ${photo.id}`)
        }

        const res = await fetch(signedData.signedUrl)
        if (!res.ok) throw new Error(`HTTP ${res.status} fetching photo ${photo.id}`)

        const buffer = await res.arrayBuffer()

        // Determine extension from storage path
        const ext = photo.storage_path.split('.').pop() ?? 'jpg'
        const kindLabel = photo.kind ?? 'photo'
        const filename = `${String(idx + 1).padStart(3, '0')}-${kindLabel}.${ext}`

        zip.file(filename, buffer)
      } catch (err) {
        logger.warn({ err, photoId: photo.id }, 'photo download: skipping photo due to fetch error')
        // Skip failed photos — partial download is better than full failure
      }
    })
  )

  logger.info(
    {
      projectId,
      total: photos.length,
      failed: downloadResults.filter((r) => r.status === 'rejected').length,
    },
    'photo download: ZIP assembly complete'
  )

  // ── Generate ZIP ──────────────────────────────────────────────────────────

  let zipBuffer: Buffer
  try {
    const zipArrayBuffer = await zip.generateAsync({
      type: 'arraybuffer',
      compression: 'DEFLATE',
      compressionOptions: { level: 6 },
    })
    zipBuffer = Buffer.from(zipArrayBuffer)
  } catch (err) {
    logger.error({ err, projectId }, 'photo download: ZIP generation failed')
    return NextResponse.json({ error: 'Failed to generate ZIP' }, { status: 500 })
  }

  // ── Build filename ────────────────────────────────────────────────────────

  const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '')
  const projectSlug = slugify(project.name ?? 'project')
  const zipFilename = `${projectSlug}-photos-${dateStr}.zip`

  return new NextResponse(zipBuffer, {
    status: 200,
    headers: {
      'Content-Type': 'application/zip',
      'Content-Disposition': `attachment; filename="${zipFilename}"`,
      'Content-Length': String(zipBuffer.length),
      'Cache-Control': 'no-store',
    },
  })
}

'use server'

import { z } from 'zod'
import { revalidatePath } from 'next/cache'
import { createClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

// ─── Types ────────────────────────────────────────────────────────────────────

type ActionResult = { error?: string }

type ReadRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'

function canWrite(role: ReadRole): boolean {
  return role === 'owner' || role === 'admin' || role === 'artist'
}

// ─── Zod schemas ──────────────────────────────────────────────────────────────

const updateCaptionSchema = z.object({
  photoId: z.string().uuid('photoId must be a valid UUID'),
  caption: z.string().max(500, 'Caption cannot exceed 500 characters'),
})

const deletePhotoSchema = z.object({
  photoId: z.string().uuid('photoId must be a valid UUID'),
})

// ─── Helper: resolve projectId from photoId (scoped to studio) ────────────────

async function resolvePhoto(
  supabase: Awaited<ReturnType<typeof createClient>>,
  photoId: string,
  studioId: string
): Promise<{ projectId: string; createdBy: string | null } | null> {
  // Join through projects to enforce studio scope
  const { data } = await supabase
    .from('project_progress_photos')
    .select('id, project_id, created_by, project:projects!inner(studio_id)')
    .eq('id', photoId)
    .maybeSingle()

  if (!data) return null

  // Type-narrow the joined project row
  const row = data as unknown as {
    id: string
    project_id: string
    created_by: string | null
    project: { studio_id: string }
  }

  if (row.project.studio_id !== studioId) return null

  return { projectId: row.project_id, createdBy: row.created_by }
}

// ─── updateProjectPhotoCaptionAction ─────────────────────────────────────────

/**
 * Update the caption on a single progress photo.
 * Role: studio member with write access (owner | admin | artist).
 */
export async function updateProjectPhotoCaptionAction({
  photoId,
  caption,
}: {
  photoId: string
  caption: string
}): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { error: 'Not authenticated' }
  if (!canWrite(auth.role as ReadRole)) return { error: 'Insufficient permissions' }

  const parsed = updateCaptionSchema.safeParse({ photoId, caption })
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const supabase = await createClient()

  const resolved = await resolvePhoto(supabase, parsed.data.photoId, auth.studioId)
  if (!resolved) return { error: 'Photo not found' }

  const { error: updateError } = await supabase
    .from('project_progress_photos')
    .update({ caption: parsed.data.caption })
    .eq('id', parsed.data.photoId)

  if (updateError) {
    logger.error({ updateError, photoId }, 'updateProjectPhotoCaptionAction failed')
    return { error: 'Failed to update caption' }
  }

  revalidatePath(`/projects/${resolved.projectId}`)
  return {}
}

// ─── deleteProjectPhotoAction ─────────────────────────────────────────────────

/**
 * Delete a progress photo.
 * Role: the uploader OR owner/admin.
 */
export async function deleteProjectPhotoAction({
  photoId,
}: {
  photoId: string
}): Promise<ActionResult> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { error: 'Not authenticated' }

  const parsed = deletePhotoSchema.safeParse({ photoId })
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const supabase = await createClient()

  const resolved = await resolvePhoto(supabase, parsed.data.photoId, auth.studioId)
  if (!resolved) return { error: 'Photo not found' }

  // Permission: uploader always can; owner/admin always can; others cannot
  const isUploader = resolved.createdBy === auth.user.id
  const isAdminOrOwner = auth.role === 'owner' || auth.role === 'admin'
  if (!isUploader && !isAdminOrOwner) {
    return { error: 'You do not have permission to delete this photo' }
  }

  // Fetch storage_path before deletion for cleanup
  const { data: photoData } = await supabase
    .from('project_progress_photos')
    .select('storage_path')
    .eq('id', parsed.data.photoId)
    .maybeSingle()

  const { error: deleteError } = await supabase
    .from('project_progress_photos')
    .delete()
    .eq('id', parsed.data.photoId)

  if (deleteError) {
    logger.error({ deleteError, photoId }, 'deleteProjectPhotoAction failed')
    return { error: 'Failed to delete photo' }
  }

  // Best-effort storage cleanup using service-role client
  if (photoData?.storage_path) {
    const { createServiceRoleClient } = await import('@/lib/supabase/server')
    const srClient = createServiceRoleClient()
    await srClient.storage
      .from('project-photos')
      .remove([photoData.storage_path])
      .catch(() => undefined)
  }

  revalidatePath(`/projects/${resolved.projectId}`)
  return {}
}

'use client'

import { useState, useTransition } from 'react'
import { toast } from 'sonner'
import { Zap, ArrowRight } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { cn } from '@/lib/utils'

// ─── Props ────────────────────────────────────────────────────────────────────

interface FlashDesignPickerProps {
  /** Whether the picker modal is open */
  open: boolean
  onOpenChange: (open: boolean) => void
  projectId: string
  /** Current reference count — used to compute display_order */
  currentReferenceCount: number
  /** Called after successfully linking designs */
  onLinked: () => void
}

// ─── Flash design not available state ────────────────────────────────────────

function NoFlashDesigns() {
  return (
    <div className="flex flex-col items-center justify-center py-12 text-center gap-3">
      <Zap className="h-10 w-10 text-[var(--color-stone)]/40" />
      <h3 className="font-serif italic text-[var(--color-onyx)] text-xl">
        No flash library yet.
      </h3>
      <p className="text-xs text-[var(--color-stone)] max-w-[240px]">
        Add designs to your flash library from the Portfolio page, then link them here.
      </p>
      <Button
        variant="outline"
        size="sm"
        asChild
        className="mt-1 gap-1.5"
      >
        <a href="/portfolio">
          Go to Portfolio
          <ArrowRight className="h-3.5 w-3.5" />
        </a>
      </Button>
    </div>
  )
}

// ─── Main component ───────────────────────────────────────────────────────────

/**
 * FlashDesignPicker — modal to pick flash designs from the studio library
 * and link them as project references.
 *
 * The `flash_designs` table does not yet exist in this codebase. The migration
 * comment in 20260422100400_project_references_extend.sql confirms this.
 * This component renders an empty-state with a link to Portfolio until that
 * migration is created and `flash_designs` is available.
 *
 * When `flash_designs` is added: replace the <NoFlashDesigns /> render with a
 * real grid fetched from `GET /api/flash-designs?studio_id={id}`.
 */
export function FlashDesignPicker({
  open,
  onOpenChange,
  projectId,
  currentReferenceCount: _currentReferenceCount,
  onLinked: _onLinked,
}: FlashDesignPickerProps) {
  const [_isPending, _startTransition] = useTransition()
  const [_flashAvailable] = useState(false) // flash_designs table not yet created

  // When flash_designs is available this will hold selected IDs
  const [_selectedIds] = useState<Set<string>>(new Set())

  // Suppress unused-var linting — these will be wired when flash_designs exists
  void _isPending
  void _startTransition
  void _selectedIds

  function handleClose() {
    onOpenChange(false)
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg bg-[var(--color-bone)]">
        <DialogHeader>
          <DialogTitle className="text-[var(--color-onyx)]">Link flash designs</DialogTitle>
          <DialogDescription className="text-[var(--color-stone)]">
            Pick designs from your flash library to add as references for this project.
          </DialogDescription>
        </DialogHeader>

        {/* Flash designs are not yet available in this codebase */}
        <NoFlashDesigns />

        <DialogFooter className="gap-2">
          <Button
            variant="outline"
            onClick={handleClose}
            className={cn('text-[var(--color-stone)]')}
          >
            Close
          </Button>
          <Button
            disabled
            className="gap-1.5"
            title="Flash library not yet available"
          >
            <Zap className="h-3.5 w-3.5" />
            Link selected
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ─── Trigger button ───────────────────────────────────────────────────────────

/**
 * Convenience trigger button rendered inside MoodboardTab.
 * Wraps the picker and manages its own open state.
 */
interface FlashDesignPickerTriggerProps {
  projectId: string
  currentReferenceCount: number
  onLinked: () => void
}

export function FlashDesignPickerTrigger({
  projectId,
  currentReferenceCount,
  onLinked,
}: FlashDesignPickerTriggerProps) {
  const [open, setOpen] = useState(false)

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className={cn(
          'w-full flex items-center justify-between px-3 py-2 rounded-lg',
          'border border-[var(--color-border)] hover:border-[var(--color-stone)]/50',
          'bg-[var(--color-bone)] text-left transition-colors',
        )}
      >
        <div className="flex items-center gap-2">
          <Zap className="h-4 w-4 text-[var(--color-stone)]" />
          <span className="text-sm text-[var(--color-stone)]">Browse flash library</span>
        </div>
        <ArrowRight className="h-3.5 w-3.5 text-[var(--color-stone)]/60 shrink-0" />
      </button>

      <FlashDesignPicker
        open={open}
        onOpenChange={setOpen}
        projectId={projectId}
        currentReferenceCount={currentReferenceCount}
        onLinked={onLinked}
      />
    </>
  )
}

// Internal helper — toast reference kept for when linking is wired up
function _flashLinkError(message: string) {
  toast.error(message)
}

void _flashLinkError

