'use client'

import { useState, useTransition, useRef } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Camera, Plus, Trash2, Download, Loader2, Pencil, Check } from 'lucide-react'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import {
  Dialog,
  DialogContent,
} from '@/components/ui/dialog'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Button } from '@/components/ui/button'
import { cn, formatDate } from '@/lib/utils'
import {
  updateProjectPhotoCaptionAction,
  deleteProjectPhotoAction,
} from '@/app/(app)/projects/photo-actions'
import type { ProjectWithSessions, ProjectProgressPhoto, ProjectPhotoKind } from '@/lib/projects/queries'

// ─── Storage URL ───────────────────────────────────────────────────────────────

function getPhotoUrl(storagePath: string): string {
  const base = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''
  return `${base}/storage/v1/object/public/project-photos/${storagePath}`
}

// ─── Slot definition ───────────────────────────────────────────────────────────

interface TimelineSlot {
  id: string
  label: string
  kind: ProjectPhotoKind
  bookingId?: string
  sessionNumber?: number
  healedDueAt?: Date
  photos: ProjectProgressPhoto[]
}

function buildSlots(
  project: ProjectWithSessions,
  photos: ProjectProgressPhoto[]
): TimelineSlot[] {
  const slots: TimelineSlot[] = []

  // 1. Before
  slots.push({
    id: 'before',
    label: 'Before',
    kind: 'before',
    photos: photos.filter((p) => p.kind === 'before' && !p.booking_id),
  })

  // 2. Per-session: Fresh + Healed
  const sessions = [...project.sessions].sort((a, b) => {
    const na = a.session_number ?? 999
    const nb = b.session_number ?? 999
    return na - nb
  })

  for (const s of sessions) {
    const sn = s.session_number ?? 0
    const label = sn > 0 ? `S${sn}` : 'Session'
    const sessionPhotos = photos.filter((p) => p.booking_id === s.id)

    slots.push({
      id: `session-${s.id}-fresh`,
      label: `${label} Fresh`,
      kind: 'after',
      bookingId: s.id,
      sessionNumber: sn,
      photos: sessionPhotos.filter((p) => p.kind === 'after'),
    })

    const sessionDate = new Date(s.scheduled_at)
    const healedDue = new Date(sessionDate)
    healedDue.setDate(healedDue.getDate() + 42) // 6 weeks

    slots.push({
      id: `session-${s.id}-healed`,
      label: `${label} Healed`,
      kind: 'healed',
      bookingId: s.id,
      sessionNumber: sn,
      healedDueAt: healedDue,
      photos: sessionPhotos.filter((p) => p.kind === 'healed'),
    })
  }

  // 3. Loose progress photos
  const progressPhotos = photos.filter((p) => p.kind === 'progress')
  if (progressPhotos.length > 0 || true) {
    slots.push({
      id: 'progress',
      label: 'Progress',
      kind: 'progress',
      photos: progressPhotos,
    })
  }

  return slots
}

// ─── Caption inline editor ────────────────────────────────────────────────────

interface CaptionEditorProps {
  photoId: string
  initial: string | null
  onSaved: (next: string) => void
}

function CaptionEditor({ photoId, initial, onSaved }: CaptionEditorProps) {
  const [editing, setEditing] = useState(false)
  const [value, setValue] = useState(initial ?? '')
  const [saving, setSaving] = useState(false)
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  async function save() {
    if (saving) return
    setSaving(true)
    const result = await updateProjectPhotoCaptionAction({ photoId, caption: value })
    setSaving(false)
    if (result.error) {
      toast.error(result.error)
      return
    }
    onSaved(value)
    setEditing(false)
  }

  if (!editing) {
    return (
      <div className="flex items-start gap-2 min-h-[1.5rem]">
        <span className="text-xs text-[var(--color-stone)] flex-1 italic">
          {value || 'Add a caption…'}
        </span>
        <button
          onClick={() => {
            setEditing(true)
            setTimeout(() => textareaRef.current?.focus(), 0)
          }}
          className="p-1 rounded text-[var(--color-stone)]/60 hover:text-[var(--color-onyx)] hover:bg-[var(--color-stone)]/10 transition-colors shrink-0"
          aria-label="Edit caption"
        >
          <Pencil className="h-3 w-3" />
        </button>
      </div>
    )
  }

  return (
    <div className="flex flex-col gap-1.5">
      <textarea
        ref={textareaRef}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        onBlur={() => void save()}
        rows={2}
        maxLength={500}
        placeholder="Add a caption…"
        className={cn(
          'w-full text-xs resize-none rounded px-2 py-1',
          'bg-[var(--color-bone)] border border-[var(--color-border)]',
          'text-[var(--color-onyx)] placeholder:text-[var(--color-stone)]/50',
          'focus:outline-none focus:border-[var(--color-stone)]/60',
        )}
      />
      <div className="flex items-center justify-end gap-1.5">
        <button
          onClick={() => void save()}
          disabled={saving}
          className="flex items-center gap-1 text-[10px] text-[var(--color-onyx)] hover:opacity-70 disabled:opacity-40"
        >
          {saving ? (
            <Loader2 className="h-3 w-3 animate-spin" />
          ) : (
            <Check className="h-3 w-3" />
          )}
          Save
        </button>
      </div>
    </div>
  )
}

// ─── Lightbox with footer controls ────────────────────────────────────────────

interface LightboxState {
  photos: ProjectProgressPhoto[]
  idx: number
  label: string
}

interface ProjectLightboxProps {
  state: LightboxState
  onClose: () => void
  onDelete: (photoId: string) => void
  canWrite: boolean
  isOwnerOrAdmin: boolean
  userId: string
}

function ProjectLightbox({
  state,
  onClose,
  onDelete,
  canWrite,
  isOwnerOrAdmin,
  userId,
}: ProjectLightboxProps) {
  const [idx, setIdx] = useState(state.idx)
  const [captionsByPhotoId, setCaptionsByPhotoId] = useState<Record<string, string | null>>({})
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null)

  const photo = state.photos[idx]
  if (!photo) return null

  const effectiveCaption =
    photo.id in captionsByPhotoId ? captionsByPhotoId[photo.id] : photo.caption

  const canDeletePhoto =
    photo.created_by === userId || isOwnerOrAdmin

  return (
    <>
      <Dialog open onOpenChange={(o) => !o && onClose()}>
        <DialogContent
          className={cn(
            'max-w-none w-screen h-screen p-0 rounded-none border-0',
            'flex flex-col bg-[var(--color-onyx)]/95',
          )}
          aria-label={`Photo ${idx + 1} of ${state.photos.length}`}
        >
          {/* Nav + close */}
          <div className="absolute top-4 left-0 right-0 flex items-center justify-between px-4 z-50">
            <span className="text-xs text-[var(--color-stone)] tabular-nums">
              {idx + 1} / {state.photos.length}
            </span>
            <Button
              variant="ghost"
              size="icon"
              onClick={onClose}
              className="h-8 w-8 text-[var(--color-stone)] hover:text-[var(--color-bone)] hover:bg-[var(--color-bone)]/10"
              aria-label="Close"
            >
              ✕
            </Button>
          </div>

          {/* Photo */}
          <div className="flex-1 flex items-center justify-center px-16 py-16 min-h-0">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={getPhotoUrl(photo.storage_path)}
              alt={effectiveCaption ?? state.label}
              className="max-h-full max-w-full object-contain rounded-md"
              draggable={false}
            />
          </div>

          {/* Prev / Next */}
          {state.photos.length > 1 && (
            <>
              <Button
                variant="ghost"
                onClick={() => setIdx((i) => Math.max(0, i - 1))}
                disabled={idx === 0}
                className="absolute left-2 top-1/2 -translate-y-1/2 h-10 w-10 text-[var(--color-stone)] hover:text-[var(--color-bone)] hover:bg-[var(--color-bone)]/10 disabled:opacity-20"
                aria-label="Previous photo"
              >
                ←
              </Button>
              <Button
                variant="ghost"
                onClick={() => setIdx((i) => Math.min(state.photos.length - 1, i + 1))}
                disabled={idx === state.photos.length - 1}
                className="absolute right-2 top-1/2 -translate-y-1/2 h-10 w-10 text-[var(--color-stone)] hover:text-[var(--color-bone)] hover:bg-[var(--color-bone)]/10 disabled:opacity-20"
                aria-label="Next photo"
              >
                →
              </Button>
            </>
          )}

          {/* Footer strip */}
          <div className="bg-[var(--color-onyx)] border-t border-[var(--color-bone)]/10 px-5 py-3 space-y-2">
            {/* Caption editor */}
            {canWrite && (
              <CaptionEditor
                key={photo.id}
                photoId={photo.id}
                initial={effectiveCaption ?? null}
                onSaved={(next) =>
                  setCaptionsByPhotoId((prev) => ({ ...prev, [photo.id]: next }))
                }
              />
            )}
            {!canWrite && effectiveCaption && (
              <p className="text-xs text-[var(--color-stone)] italic">{effectiveCaption}</p>
            )}

            {/* Actions */}
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-1.5">
                {photo.taken_at && (
                  <span className="text-[10px] text-[var(--color-stone)]">
                    {formatDate(photo.taken_at, { month: 'short', day: 'numeric', year: 'numeric' })}
                  </span>
                )}
              </div>

              <div className="flex items-center gap-2">
                {/* Download single */}
                <a
                  href={getPhotoUrl(photo.storage_path)}
                  download={`photo-${photo.id}.jpg`}
                  className={cn(
                    'text-xs text-[var(--color-stone)] hover:text-[var(--color-bone)] transition-colors',
                    'flex items-center gap-1',
                  )}
                >
                  <Download className="h-3.5 w-3.5" />
                  Download
                </a>

                {/* Delete */}
                {canDeletePhoto && (
                  <button
                    onClick={() => setConfirmDeleteId(photo.id)}
                    className="text-xs text-[var(--color-rust)]/70 hover:text-[var(--color-rust)] transition-colors flex items-center gap-1"
                    aria-label="Delete photo"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                    Delete
                  </button>
                )}
              </div>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Delete confirmation */}
      <AlertDialog
        open={confirmDeleteId !== null}
        onOpenChange={(open) => !open && setConfirmDeleteId(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this photo?</AlertDialogTitle>
            <AlertDialogDescription>
              The photo will be permanently removed from the project. This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (confirmDeleteId) {
                  onDelete(confirmDeleteId)
                  setConfirmDeleteId(null)
                  // Close lightbox if it was the only photo or the current photo
                  if (state.photos.length <= 1) onClose()
                  else setIdx((i) => Math.max(0, i - 1))
                }
              }}
              className="bg-[var(--color-destructive)] text-[var(--color-destructive-foreground)] hover:bg-[var(--color-destructive)]/90"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

// ─── Photo slot ───────────────────────────────────────────────────────────────

interface PhotoSlotProps {
  slot: TimelineSlot
  canWrite: boolean
  projectId: string
  onUploadComplete: () => void
  onOpenLightbox: (photos: ProjectProgressPhoto[], idx: number, label: string) => void
}

function PhotoSlot({ slot, canWrite, projectId, onUploadComplete, onOpenLightbox }: PhotoSlotProps) {
  const [uploading, setUploading] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const now = new Date()
  const isHealedOverdue =
    slot.kind === 'healed' &&
    slot.photos.length === 0 &&
    slot.healedDueAt != null &&
    slot.healedDueAt < now

  const hasPhotos = slot.photos.length > 0
  const firstPhoto = slot.photos[0]

  async function handleFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return

    // Reset input so the same file can be re-selected after a failure
    e.target.value = ''

    setUploading(true)
    try {
      const fd = new FormData()
      fd.append('file', file)
      fd.append('slot_type', slot.kind)
      if (slot.bookingId) fd.append('booking_id', slot.bookingId)
      if (slot.sessionNumber != null) fd.append('session_number', String(slot.sessionNumber))

      const res = await fetch(`/api/projects/${projectId}/photos/upload`, {
        method: 'POST',
        body: fd,
      })

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Upload failed')
      }

      toast.success('Photo added')
      onUploadComplete()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to upload photo')
    } finally {
      setUploading(false)
    }
  }

  return (
    <div className="shrink-0 flex flex-col gap-1.5 w-28">
      <span className="text-[11px] font-medium text-[var(--color-stone)] truncate">{slot.label}</span>

      {/* Photo tile or placeholder */}
      <div
        className={cn(
          'relative w-28 h-28 rounded-lg overflow-hidden border',
          hasPhotos
            ? 'border-[var(--color-border)] cursor-pointer group'
            : 'border-dashed border-[var(--color-border)]',
          isHealedOverdue && 'border-[var(--color-rust)]/50',
        )}
        onClick={() => hasPhotos && firstPhoto && onOpenLightbox(slot.photos, 0, slot.label)}
        role={hasPhotos ? 'button' : undefined}
        aria-label={hasPhotos ? `View ${slot.label} photos` : undefined}
        tabIndex={hasPhotos ? 0 : undefined}
        onKeyDown={(e) => {
          if (hasPhotos && (e.key === 'Enter' || e.key === ' ')) {
            e.preventDefault()
            firstPhoto && onOpenLightbox(slot.photos, 0, slot.label)
          }
        }}
      >
        {hasPhotos && firstPhoto ? (
          <>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={getPhotoUrl(firstPhoto.storage_path)}
              alt={firstPhoto.caption ?? slot.label}
              className="h-full w-full object-cover group-hover:opacity-90 transition-opacity"
              draggable={false}
            />
            {slot.photos.length > 1 && (
              <span className="absolute bottom-1 right-1 bg-[var(--color-onyx)]/70 text-[var(--color-bone)] text-[10px] px-1.5 py-0.5 rounded">
                +{slot.photos.length - 1}
              </span>
            )}
          </>
        ) : (
          <div className="flex flex-col items-center justify-center h-full gap-1">
            {isHealedOverdue ? (
              <div className="flex flex-col items-center gap-1 px-1 text-center">
                <span className="w-2 h-2 rounded-full bg-[var(--color-rust)]" />
                <span className="text-[10px] text-[var(--color-stone)] leading-tight">
                  Healed photo due
                </span>
              </div>
            ) : (
              <Camera className="h-5 w-5 text-[var(--color-stone)]/40" />
            )}
          </div>
        )}
      </div>

      {/* Hidden file input */}
      <input
        ref={fileInputRef}
        type="file"
        accept="image/jpeg,image/png,image/webp,image/heic"
        className="sr-only"
        onChange={(e) => void handleFileChange(e)}
        aria-label={`Upload ${slot.label} photo`}
      />

      {/* Upload / upload-now button */}
      {canWrite && (
        <>
          {isHealedOverdue ? (
            <button
              onClick={() => fileInputRef.current?.click()}
              disabled={uploading}
              className={cn(
                'flex items-center justify-center gap-1 h-7 rounded text-[10px] font-medium',
                'border border-[var(--color-rust)]/50 text-[var(--color-rust)]',
                'hover:bg-[var(--color-rust)]/5 transition-colors',
                'disabled:opacity-50',
              )}
            >
              {uploading ? <Loader2 className="h-3 w-3 animate-spin" /> : null}
              Upload now
            </button>
          ) : (
            <button
              onClick={() => fileInputRef.current?.click()}
              disabled={uploading}
              className={cn(
                'flex items-center justify-center gap-1 h-7 rounded text-[10px]',
                'border border-dashed border-[var(--color-border)]',
                'text-[var(--color-stone)] hover:text-[var(--color-onyx)]',
                'hover:border-[var(--color-stone)]/50 transition-colors',
                'disabled:opacity-50',
              )}
            >
              {uploading ? (
                <Loader2 className="h-3 w-3 animate-spin" />
              ) : (
                <Plus className="h-3 w-3" />
              )}
              <span>Add</span>
            </button>
          )}
        </>
      )}
    </div>
  )
}

// ─── Main timeline ─────────────────────────────────────────────────────────────

interface PhotoProgressionTimelineProps {
  project: ProjectWithSessions
  photos: ProjectProgressPhoto[]
  role: string
  userId: string
  onRefresh: () => void
}

export function PhotoProgressionTimeline({
  project,
  photos,
  role,
  userId,
  onRefresh,
}: PhotoProgressionTimelineProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [lightbox, setLightbox] = useState<LightboxState | null>(null)
  const [downloading, setDownloading] = useState(false)

  const canWrite = role === 'owner' || role === 'admin' || role === 'artist'
  const isOwnerOrAdmin = role === 'owner' || role === 'admin'

  const slots = buildSlots(project, photos)

  function handleUploadComplete() {
    startTransition(() => {
      router.refresh()
      onRefresh()
    })
  }

  async function handleDelete(photoId: string) {
    const result = await deleteProjectPhotoAction({ photoId })
    if (result.error) {
      toast.error(result.error)
      return
    }
    toast.success('Photo deleted')
    startTransition(() => {
      router.refresh()
      onRefresh()
    })
  }

  async function handleDownloadZip() {
    setDownloading(true)
    try {
      const res = await fetch(`/api/projects/${project.id}/photos/download`)
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Download failed')
      }

      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url

      // Use filename from Content-Disposition if present
      const cd = res.headers.get('content-disposition')
      const match = cd?.match(/filename="([^"]+)"/)
      a.download = match?.[1] ?? `photos-${project.id}.zip`

      a.click()
      URL.revokeObjectURL(url)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Download failed')
    } finally {
      setDownloading(false)
    }
  }

  return (
    <div className="space-y-4">
      {/* Actions row */}
      <div className="flex items-center justify-between">
        <p className="text-xs text-[var(--color-stone)]">
          {photos.length} photo{photos.length !== 1 ? 's' : ''} across {project.sessions.length} session{project.sessions.length !== 1 ? 's' : ''}
        </p>
        <div className="flex items-center gap-3">
          <button
            onClick={() => void handleDownloadZip()}
            disabled={downloading || photos.length === 0}
            className={cn(
              'flex items-center gap-1.5 text-xs text-[var(--color-stone)]',
              'hover:text-[var(--color-onyx)] transition-colors',
              'disabled:opacity-40 disabled:cursor-not-allowed',
            )}
          >
            {downloading ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Download className="h-3.5 w-3.5" />
            )}
            Download all (.zip)
          </button>
          <button
            disabled
            title="Share set — coming in v2"
            className="text-xs text-[var(--color-stone)]/40 cursor-not-allowed"
          >
            Share set
          </button>
        </div>
      </div>

      {/* Horizontal scrollable strip */}
      <div className="flex gap-4 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-[var(--color-border)]">
        {slots.map((slot) => (
          <PhotoSlot
            key={slot.id}
            slot={slot}
            canWrite={canWrite}
            projectId={project.id}
            onUploadComplete={handleUploadComplete}
            onOpenLightbox={(p, idx, lbl) => setLightbox({ photos: p, idx, label: lbl })}
          />
        ))}
      </div>

      {/* Lightbox */}
      {lightbox && (
        <ProjectLightbox
          state={lightbox}
          onClose={() => setLightbox(null)}
          onDelete={(id) => void handleDelete(id)}
          canWrite={canWrite}
          isOwnerOrAdmin={isOwnerOrAdmin}
          userId={userId}
        />
      )}
    </div>
  )
}

