export async function reorderProjectReferences(
  _studioId: string,
  projectId: string,
  orderedIds: string[]
): Promise<void> {
  const supabase = await createClient()

  const updates = orderedIds.map((id, index) =>
    supabase
      .from('project_references')
      .update({ display_order: index })
      .eq('id', id)
      .eq('project_id', projectId)
  )

  const results = await Promise.all(updates)
  const failed = results.find((r) => r.error)
  if (failed?.error) {
    logger.error({ error: failed.error, projectId }, 'reorderProjectReferences failed')
    throw new Error('Failed to reorder references')
  }
}

